if(EditorApplication.isPlaying)throw new System.Exception("Edit only");
string D="ArtSource/Pipeline/Review/BriarwickWoodland01";var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var root=GameObject.Find("Woodland01 - Mini Nature limited review");
string Path(Transform t){return t.parent==null?t.name:Path(t.parent)+"/"+t.name;}
var old=Newtonsoft.Json.Linq.JArray.Parse(System.IO.File.ReadAllText(D+"/SceneBefore.json"));var current=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).GroupBy(t=>Path(t)).ToDictionary(g=>g.Key,g=>new System.Collections.Generic.Queue<Transform>(g));var differences=new System.Collections.Generic.List<string>();
foreach(var entry in old){string p=(string)entry["path"];if(!current.ContainsKey(p)){differences.Add("Missing "+p);continue;}var components=current[p].Dequeue().GetComponents<Component>();foreach(var c in entry["components"]){var component=components.FirstOrDefault(x=>x!=null&&x.GetType().FullName==(string)c["type"]);if(component==null||EditorJsonUtility.ToJson(component)!=(string)c["json"])differences.Add(p+" "+(string)c["type"]);}}
var fs=root.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.StartsWith("BW_")).ToArray();var materials=fs.SelectMany(f=>f.GetComponent<Renderer>().sharedMaterials).Distinct().ToArray();var defects=new System.Collections.Generic.List<string>();foreach(var f in fs){var m=f.sharedMesh;if(m==null){defects.Add(f.name+" missing mesh");continue;}if(m.uv.Length!=m.vertexCount||m.normals.Length!=m.vertexCount||m.vertices.Any(v=>float.IsNaN(v.x)||float.IsNaN(v.y)||float.IsNaN(v.z))||m.normals.Any(v=>float.IsNaN(v.x)||v.sqrMagnitude<.00001f))defects.Add(f.name+" invalid UV/normal/vertex");if(m.subMeshCount!=f.GetComponent<Renderer>().sharedMaterials.Length)defects.Add(f.name+" submesh mismatch");}
foreach(var m in materials)if(m==null||m.shader.name!="Universal Render Pipeline/Lit"||!m.shader.isSupported||m.GetTexture("_BaseMap")==null||m.GetFloat("_Surface")!=0||m.GetFloat("_Metallic")!=0||(m.name.Contains("Leaves")&&(m.GetFloat("_AlphaClip")!=1||m.GetFloat("_Cull")!=0)))defects.Add("Invalid material "+m?.name);
var originals=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>t.name=="Woodland_CombinedCanopyMasses_PROXY"||t.name=="Woodland_CombinedTrunkMasses_PROXY").ToArray();var proxyChecks=new System.Collections.Generic.List<object>();foreach(var o in originals){string suffix=o.name.Contains("Canopy")?"Canopy":"Trunks";var original=o.GetComponent<MeshFilter>().sharedMesh;var remainder=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/BlightBloom/Art/Environment/Briarwick/Woodland01/ProxyMeshes/Woodland01_Remainder_"+suffix+".asset");var selected=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/BlightBloom/Art/Environment/Briarwick/Woodland01/ProxyMeshes/Woodland01_Selected_"+suffix+".asset");var recombined=remainder.triangles.Concat(selected.triangles).OrderBy(x=>x).ToArray();proxyChecks.Add(new{suffix,originalDisabled=!o.gameObject.activeSelf,verticesPreserved=original.vertices.SequenceEqual(remainder.vertices)&&original.vertices.SequenceEqual(selected.vertices),triangleIndicesPreserved=recombined.SequenceEqual(original.triangles.OrderBy(x=>x)),remainderTriangles=remainder.triangles.Length/3,selectedTriangles=selected.triangles.Length/3});}
var buildings=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>()).Where(r=>r.gameObject.activeInHierarchy&&!r.transform.IsChildOf(root.transform)&&r.GetComponent<MeshFilter>()!=null&&AssetDatabase.GetAssetPath(r.GetComponent<MeshFilter>().sharedMesh).Contains("Architecture")).ToArray();var intersections=fs.SelectMany(f=>buildings.Where(b=>b.bounds.Intersects(f.GetComponent<Renderer>().bounds)).Select(b=>f.name+" / "+b.name)).ToArray();
var result=new{scene=scene.path,sceneSaved=!scene.isDirty,preexistingObjectsChecked=old.Count,preexistingComponentDifferences=differences,proxyChecks,vegetationInstances=fs.Length,triangles=fs.Sum(f=>f.sharedMesh.triangles.Length/3),renderers=fs.Length,baseSubmeshSubmissions=fs.Sum(f=>f.sharedMesh.subMeshCount),sharedMaterials=materials.Length,trunkColliders=root.GetComponentsInChildren<Collider>().Length,defects,buildingBoundsIntersections=intersections};System.IO.File.WriteAllText(D+"/Validation.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;
